public boolean onItemSingleTapUp(final int index, final OverlayItem item) {
  try {
    Toast.makeText(OpenStreetMap.this, "Latitude :" + item.mGeoPoint.getLatitudeE6() + "\n" + "Longitude: " + item.mGeoPoint.getLongitudeE6(), Toast.LENGTH_LONG).show();
  } catch (NullPointerException e) {
    // Handle the null pointer exception, e.g., by logging or showing a different message
    Toast.makeText(OpenStreetMap.this, "Invalid item or geo point", Toast.LENGTH_LONG).show();
  }
  return true;
}
